<script lang="ts">
	import type { Attachment } from 'svelte/attachments';
	import { loader } from '#lib/motion.js';

	/*
		First-visit loader: the CSL logo builds itself (ground line, walls, roof, red block,
		letters traced then filled, hammer drop, wordmark), then a curtain lifts off the page.
		Artwork and choreography come from the "CSL Loading Screen" design canvas, cut from a
		7s loop to a single ~3.1s pass (see --pace).

		The inline script in app.html adds `has-loader` to <html> before first paint, only on
		the first page of a session and never under reduced motion. Without that class this
		markup stays display:none and is removed on mount. Any key, click, wheel or touch skips it.
	*/

	let show = $state(true);
	let leaving = $state(false);

	function end() {
		show = false;
		document.documentElement.classList.remove('has-loader');
	}

	const run: Attachment<HTMLElement> = (el) => {
		if (!document.documentElement.classList.contains('has-loader')) {
			end();
			return;
		}

		const timers: ReturnType<typeof setTimeout>[] = [];
		let left = false;
		const leave = () => {
			if (left) return;
			left = true;
			leaving = true;
			// Page reveals start now, so the hero animates in as the curtain lifts.
			loader.finish();
			timers.push(setTimeout(end, 1400)); // in case transitionend never fires
		};

		// Only the artwork's animations (the overlay's own failsafe fade must not count).
		const anims = el.querySelector('svg')?.getAnimations?.({ subtree: true }) ?? [];
		Promise.all(anims.map((a) => a.finished)).then(
			() => timers.push(setTimeout(leave, 380)),
			leave
		);
		timers.push(setTimeout(leave, 7000));

		const skip = () => leave();
		const opts = { passive: true };
		window.addEventListener('keydown', skip);
		window.addEventListener('pointerdown', skip, opts);
		window.addEventListener('wheel', skip, opts);
		window.addEventListener('touchstart', skip, opts);
		return () => {
			timers.forEach(clearTimeout);
			window.removeEventListener('keydown', skip);
			window.removeEventListener('pointerdown', skip);
			window.removeEventListener('wheel', skip);
			window.removeEventListener('touchstart', skip);
		};
	};

	function ontransitionend(event: TransitionEvent) {
		if (event.target === event.currentTarget && event.propertyName === 'clip-path') end();
	}
</script>

{#if show}
	<div class={['loader', leaving && 'is-leaving']} aria-hidden="true" {@attach run} {ontransitionend}>
