<style>
	.loader {
		/* Pace of the whole build: 1 = the 2.3s cut, higher is slower. */
		--pace: 1.35;
		position: fixed;
		inset: 0;
		z-index: 200;
		display: none;
		place-items: center;
		background: var(--paper);
		clip-path: inset(0 0 0 0);
		transition: clip-path 1s var(--ease-in-out);
	}
	:global(html.has-loader) .loader {
		display: grid;
		/* Failsafe: if the app script never runs, get out of the way anyway. */
		animation: failsafe 0.4s ease 9s both;
	}
	.loader.is-leaving {
		clip-path: inset(0 0 100% 0);
	}
	svg {
		overflow: visible;
	}
	.loader > svg {
		display: block;
		width: min(420px, 68vw);
		height: auto;
		transition:
			transform 0.8s var(--ease-in-out),
			opacity 0.45s var(--ease-out);
	}
	.is-leaving > svg {
		transform: translateY(-6vh);
		opacity: 0;
	}
	/* Nested svgs clip the wordmark lines so they rise out of nothing. */
	.loader > svg svg {
		overflow: hidden;
	}

	/* Ground line and red block */
	.found,
	.panel {
		fill: var(--logo-red);
		transform-box: fill-box;
	}
	.found {
		transform-origin: 50% 50%;
		animation: grow-x calc(0.32s * var(--pace)) cubic-bezier(0.22, 1, 0.36, 1) calc(0.05s * var(--pace)) both;
	}
	.panel {
		transform-origin: 50% 100%;
		animation: grow-y calc(0.3s * var(--pace)) cubic-bezier(0.22, 1, 0.36, 1) calc(0.8s * var(--pace)) both;
	}

	/* House linework, drawn on */
	.ln {
		fill: none;
		stroke: var(--logo-line);
		stroke-linecap: butt;
		stroke-linejoin: miter;
		stroke-miterlimit: 10;
		stroke-dasharray: 1 1;
		animation: draw calc(var(--d) * var(--pace)) cubic-bezier(0.45, 0, 0.2, 1) calc(var(--at) * var(--pace)) both;
	}
	.wl {
		stroke-width: 21;
		--at: 0.18s;
		--d: 0.26s;
	}
	.post {
		stroke-width: 22;
		--at: 0.24s;
		--d: 0.3s;
	}
	.wr {
		stroke-width: 20;
		--at: 0.32s;
		--d: 0.2s;
	}
	.base {
		stroke-width: 16;
		--at: 0.38s;
		--d: 0.26s;
	}
	.roof {
		stroke-width: 19;
		--at: 0.5s;
		--d: 0.44s;
		animation-timing-function: cubic-bezier(0.65, 0, 0.35, 1);
	}

	/* Letters: outline traces, fill fades in, then the outline fades away */
	.lt {
		fill: var(--logo-blue);
		/* The gap around each letter is painted in the page color, as in the logo. */
		stroke: var(--paper);
		stroke-width: 26;
		stroke-linejoin: round;
		paint-order: stroke fill;
	}
	.fill-c {
		animation: fade-in calc(0.16s * var(--pace)) ease-out calc(1.3s * var(--pace)) both;
	}
	.fill-s {
		animation: fade-in calc(0.16s * var(--pace)) ease-out calc(1.42s * var(--pace)) both;
	}
	.fill-l {
		transform-box: fill-box;
		transform-origin: 50% 100%;
		animation:
			fade-in calc(0.14s * var(--pace)) ease-out calc(1.52s * var(--pace)) both,
			squash calc(0.16s * var(--pace)) ease-in-out calc(1.81s * var(--pace)) both;
	}
	.tr {
		fill: none;
		stroke: var(--logo-blue);
		stroke-width: 5;
		stroke-linejoin: round;
		stroke-dasharray: 1 1;
		animation: trace calc(var(--d) * var(--pace)) cubic-bezier(0.45, 0, 0.25, 1) calc(var(--at) * var(--pace)) both;
	}
	.tr-c {
		--at: 1.02s;
		--d: 0.54s;
	}
	.tr-s {
		--at: 1.12s;
		--d: 0.56s;
	}
	.tr-l {
		--at: 1.24s;
		--d: 0.5s;
	}

	/* Hammer drops onto the L */
	.hammer {
		fill: var(--logo-line);
		fill-rule: evenodd;
		transform-box: fill-box;
		transform-origin: 50% 100%;
		animation: hammer calc(0.44s * var(--pace)) linear calc(1.56s * var(--pace)) both;
	}

	/* Wordmark */
	.tx {
		fill: var(--logo-line);
		fill-rule: evenodd;
		animation: rise calc(0.38s * var(--pace)) cubic-bezier(0.16, 1, 0.3, 1) calc(var(--at) * var(--pace)) both;
	}
	.tx1 {
		--at: 1.86s;
	}
	.tx2 {
		--at: 1.96s;
	}

	@keyframes grow-x {
		from {
			transform: scaleX(0);
		}
	}
	@keyframes grow-y {
		from {
			transform: scaleY(0);
		}
	}
	@keyframes draw {
		from {
			stroke-dashoffset: 1;
		}
		to {
			stroke-dashoffset: 0;
		}
	}
	@keyframes fade-in {
		from {
			opacity: 0;
		}
	}
	@keyframes trace {
		0% {
			stroke-dashoffset: 1;
			opacity: 1;
		}
		65% {
			stroke-dashoffset: 0;
			opacity: 1;
		}
		80% {
			stroke-dashoffset: 0;
			opacity: 1;
		}
		100% {
			stroke-dashoffset: 0;
			opacity: 0;
		}
	}
	@keyframes squash {
		40% {
			transform: scaleY(0.955);
		}
		75% {
			transform: scaleY(1.012);
		}
	}
	@keyframes hammer {
		0% {
			opacity: 0;
			transform: translate(0, -150px) rotate(-38deg);
			animation-timing-function: cubic-bezier(0.55, 0, 1, 0.45);
		}
		10% {
			opacity: 1;
			transform: translate(0, -108px) rotate(-30deg);
			animation-timing-function: cubic-bezier(0.55, 0, 1, 0.45);
		}
		57% {
			transform: translate(0, 0) rotate(5deg);
			animation-timing-function: cubic-bezier(0.2, 0.8, 0.3, 1);
		}
		72% {
			transform: translate(0, -12px) rotate(-3deg);
			animation-timing-function: ease-in-out;
		}
		86% {
			transform: translate(0, 0) rotate(1deg);
			animation-timing-function: ease-in-out;
		}
		100% {
			opacity: 1;
			transform: translate(0, 0) rotate(0deg);
		}
	}
	@keyframes rise {
		from {
			opacity: 0;
			transform: translateY(112px);
		}
	}
	@keyframes failsafe {
		to {
			opacity: 0;
			visibility: hidden;
		}
	}

	@media (prefers-reduced-motion: reduce) {
		.loader {
			display: none !important;
		}
	}
</style>
